  "mutable": false,
  "keywords": [
    "builtin"
  ],
  "metadata": [],
  "inputs": {
    "stringInput": {
      "title": "stringInput",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "type": "string",
        "enum": [
          "Value1",
          "Value2",
          "Value3"
        ]
      },
      "literalDataDomains": [
        {
          "default": true,
          "dataType": {
            "name": "string"
          },
          "valueDefinition": [
            "Value1",
            "Value2",
            "Value3"
          ]
        }
      ]
    },
    "measureInput": {
      "title": "Numerical Value with UOM Example",
      "description": "This is an example of a NUMERIC literal with an associated unit of measure.",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "oneOf": [
          {
            "type": "object",
            "required": [
              "measurement",
              "uom"
            ],
            "properties": {
              "measurement": {
                "type": "number"
              },
              "uom": {
                "type": "string",
                "enum": [
                  "m/s²",
                  "km/min²"
                ]
              },
              "reference": {
                "type": "string",
                "format": "uri"
              }
            }
          },
          {
            "type": "number",
            "format": "float"
          }
        ]
      },
      "literalDataDomains": [
        {
          "default": true,
          "dataType": {
            "name": "float"
          },
          "valueDefinition": {
            "anyValue": false
          },
          "UOMs": {
            "supported": [
              {
                "uom": "m/s²"
              },
              {
                "uom": "km/min²"
              }
            ],
            "default": {
              "uom": "m/s²"
            }
          }
        }
      ]
    },
    "dateInput": {
      "title": "Date Literal Input Example",
      "description": "This is an example of a DATE literal input.",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "type": "string",
        "format": "date-time"
